/* Collections: the 30 iconic peaks shown by default, and the world's 30 highest
   (Wikipedia "List of highest mountains on Earth", independent summits only). */
(() => {
  const ICONIC = ["everest", "k2", "kangchenjunga", "lhotse", "makalu", "chooyu", "annapurna", "aconcagua", "amadablam",
    "huascaran", "denali", "chimborazo", "kilimanjaro", "elbrus", "kenya", "ararat", "vinson", "puncakjaya", "montblanc",
    "matterhorn", "rainier", "grandteton", "eiger", "fuji", "cook", "fitzroy", "halfdome", "kosciuszko", "bennevis", "table"];
  const TOP30 = ["everest", "k2", "kangchenjunga", "lhotse", "makalu", "chooyu", "dhaulagiri", "manaslu", "nangaparbat",
    "annapurna", "g1", "broadpeak", "g2", "shishapangma", "gyachungkang", "annapurna2", "g4", "himalchuli", "distaghil",
    "ngadichuli", "khunyang", "masherbrum", "nandadevi", "chomolonzo", "batura", "rakaposhi", "namchabarwa", "kanjutsar",
    "kamet", "dhaulagiri2"];
  for (const p of window.ATLAS.peaks) {
    if (ICONIC.includes(p.id)) p.tags.push("Iconic");
    if (TOP30.includes(p.id)) p.tags.push("Top30");
  }
})();
